// Vapi sends: { message: { type: 'tool-calls', toolCallList: [...], call: {...} } }
const msg = $input.first().json.body.message;
const toolCall = msg.toolCallList[0];
const args = typeof toolCall.function.arguments === 'string'
  ? JSON.parse(toolCall.function.arguments)
  : toolCall.function.arguments;

const ticketId = 'MR-' + Date.now().toString(36).toUpperCase();

return [{
  json: {
    ticket_id: ticketId,
    tool_call_id: toolCall.id,
    received_at: new Date().toISOString(),
    caller_id: (msg.call && msg.call.customer && msg.call.customer.number) || '',
    tenant_name: args.tenant_name || '',
    callback_number: args.callback_number || '',
    property_address: args.property_address || '',
    unit: args.unit || '',
    issue_category: args.issue_category || 'other',
    issue_description: args.issue_description || '',
    urgency: args.urgency || 'routine',
    permission_to_enter: args.permission_to_enter === true ? 'yes' : 'no',
    pets_on_site: args.pets_on_site || '',
    preferred_time: args.preferred_time || '',
    status: 'new'
  }
}];
